1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { createClient } from "@/lib/supabase/server";
5	import { logActivity } from "@/lib/activity-log";
6	
7	export type PaymentMethodState = { error: string | null };
8	
9	export async function addPaymentMethod(
10	  businessId: string,
11	  _prevState: PaymentMethodState,
12	  formData: FormData,
13	): Promise<PaymentMethodState> {
14	  const name = (formData.get("name") as string)?.trim();
15	
16	  if (!name) {
17	    return { error: "Nama metode pembayaran wajib diisi." };
18	  }
19	
20	  const supabase = await createClient();
21	  const { error } = await supabase.from("custom_payment_methods").insert({
22	    business_id: businessId,
23	    name,
24	  });
25	
26	  if (error) {
27	    return { error: error.message };
28	  }
29	
30	  await logActivity(
31	    supabase,
32	    businessId,
33	    "pengaturan",
34	    "sukses",
35	    `Metode pembayaran baru: ${name}`,
36	  );
37	  revalidatePath(`/business/${businessId}/settings`);
38	  return { error: null };
39	}
40	
41	export async function deletePaymentMethod(businessId: string, methodId: string) {
42	  const supabase = await createClient();
43	  await supabase.from("custom_payment_methods").delete().eq("id", methodId).eq("business_id", businessId);
44	  revalidatePath(`/business/${businessId}/settings`);
45	}
46	
47	export type KitchenPrinterState = { error: string | null };
48	
49	export async function addKitchenPrinter(
50	  businessId: string,
51	  _prevState: KitchenPrinterState,
52	  formData: FormData,
53	): Promise<KitchenPrinterState> {
54	  const name = (formData.get("name") as string)?.trim();
55	  const connectionType = formData.get("connectionType") as string;
56	  const address = (formData.get("address") as string)?.trim();
57	  const categories = formData.getAll("categories").map((c) => String(c));
58	
59	  if (!name) {
60	    return { error: "Nama stasiun printer wajib diisi." };
61	  }
62	  if (connectionType !== "bluetooth" && connectionType !== "lan") {
63	    return { error: "Pilih jenis koneksi dulu." };
64	  }
65	
66	  const supabase = await createClient();
67	  const { error } = await supabase.from("kitchen_printers").insert({
68	    business_id: businessId,
69	    name,
70	    connection_type: connectionType,
71	    address: address || null,
72	    categories,
73	  });
74	
75	  if (error) {
76	    return { error: error.message };
77	  }
78	
79	  await logActivity(
80	    supabase,
81	    businessId,
82	    "pengaturan",
83	    "sukses",
84	    `Printer dapur baru: ${name}`,
85	    connectionType === "lan" ? `LAN${address ? ` · ${address}` : ""}` : "Bluetooth",
86	  );
87	  revalidatePath(`/business/${businessId}/settings`);
88	  return { error: null };
89	}
90	
91	export async function deleteKitchenPrinter(businessId: string, printerId: string) {
92	  const supabase = await createClient();
93	  await supabase.from("kitchen_printers").delete().eq("id", printerId).eq("business_id", businessId);
94	  revalidatePath(`/business/${businessId}/settings`);
95	}
96	
97	export type TaxServiceState = { error: string | null; saved: boolean };
98	
99	export async function updateTaxService(
100	  businessId: string,
101	  _prevState: TaxServiceState,
102	  formData: FormData,
103	): Promise<TaxServiceState> {
104	  const taxEnabled = formData.get("taxEnabled") === "on";
105	  const serviceEnabled = formData.get("serviceEnabled") === "on";
106	  const taxRate = Number(formData.get("taxRate"));
107	  const serviceRate = Number(formData.get("serviceRate"));
108	
109	  if (taxEnabled && (Number.isNaN(taxRate) || taxRate < 0 || taxRate > 100)) {
110	    return { error: "Tarif PPN harus 0–100%.", saved: false };
111	  }
112	  if (serviceEnabled && (Number.isNaN(serviceRate) || serviceRate < 0 || serviceRate > 100)) {
113	    return { error: "Tarif biaya layanan harus 0–100%.", saved: false };
114	  }
115	
116	  const supabase = await createClient();
117	  const { error } = await supabase
118	    .from("businesses")
119	    .update({
120	      tax_enabled: taxEnabled,
121	      tax_rate: taxEnabled ? taxRate : 0,
122	      service_enabled: serviceEnabled,
123	      service_rate: serviceEnabled ? serviceRate : 0,
124	    })
125	    .eq("id", businessId);
126	
127	  if (error) {
128	    return { error: error.message, saved: false };
129	  }
130	
131	  await logActivity(
132	    supabase,
133	    businessId,
134	    "pengaturan",
135	    "sukses",
136	    "Pajak & biaya layanan diperbarui",
137	    `PPN ${taxEnabled ? `${taxRate}%` : "nonaktif"} · Layanan ${serviceEnabled ? `${serviceRate}%` : "nonaktif"}`,
