10	  type Period,
11	} from "./period";
12	
13	const DONUT_PALETTE = ["#0f766e", "#34d399", "#fcd34d", "#a78bfa", "#fb923c", "#60a5fa", "#f87171"];
14	const CATEGORY_PALETTE = ["#0f766e", "#10b981", "#34d399", "#6ee7b7", "#a7f3d0", "#d1fae5"];
15	const MEDALS = ["🥇", "🥈", "🥉"];
16	
17	function formatRupiah(value: number) {
18	  const sign = value < 0 ? "-" : "";
19	  return `${sign}Rp${Math.round(Math.abs(value)).toLocaleString("id-ID")}`;
20	}
21	
22	function formatDateTime(iso: string) {
23	  return new Date(iso).toLocaleString("id-ID", {
24	    day: "2-digit",
25	    month: "short",
26	    hour: "2-digit",
27	    minute: "2-digit",
28	    timeZone: REPORT_TIMEZONE,
29	  });
30	}
31	
32	const hourFormatter = new Intl.DateTimeFormat("en-US", {
33	  hour: "numeric",
34	  hourCycle: "h23",
35	  timeZone: REPORT_TIMEZONE,
36	});
37	
38	function wibHour(iso: string) {
39	  return Number(hourFormatter.format(new Date(iso)));
40	}
41	
42	function buildDonutSegments(entries: [string, number][], total: number) {
43	  const R = 28;
44	  const cx = 40;
45	  const cy = 40;
46	  // Satu metode = lingkaran penuh; path arc 360° akan degenerate (titik awal == akhir).
47	  if (entries.length === 1) {
48	    return [{ d: null, color: DONUT_PALETTE[0] }];
49	  }
50	  let angle = -Math.PI / 2;
51	  return entries.map(([, val], i) => {
52	    const sweep = (val / total) * 2 * Math.PI;
53	    const x1 = cx + R * Math.cos(angle);
54	    const y1 = cy + R * Math.sin(angle);
55	    const x2 = cx + R * Math.cos(angle + sweep);
56	    const y2 = cy + R * Math.sin(angle + sweep);
57	    const large = sweep > Math.PI ? 1 : 0;
58	    angle += sweep;
59	    return {
60	      d: `M${cx},${cy} L${x1},${y1} A${R},${R} 0 ${large},1 ${x2},${y2} Z`,
61	      color: DONUT_PALETTE[i % DONUT_PALETTE.length],
62	    };
63	  });
64	}
65	
66	export default async function ReportsPage({
67	  params,
68	  searchParams,
69	}: {
70	  params: Promise<{ businessId: string }>;
71	  searchParams: Promise<{ period?: string; from?: string; to?: string }>;
72	}) {
73	  const { businessId } = await params;
74	  const { period: periodParam, from, to } = await searchParams;
75	  const period = parsePeriod(periodParam);
76	  const { fromIso, toIsoExclusive } = getPeriodRange(period, from, to);
77	
78	  const supabase = await createClient();
79	
80	  const { data: business } = await supabase
81	    .from("businesses")
82	    .select("id, name")
83	    .eq("id", businessId)
84	    .single();
85	
86	  if (!business) {
87	    notFound();
88	  }
89	
90	  let txQuery = supabase
91	    .from("transactions")
92	    .select(
93	      "id, invoice_number, date, subtotal, total, total_cost, gross_profit, is_split, voided, transaction_items(product_id, name, category, price, qty), transaction_payments(method, amount)",
94	    )
95	    .eq("business_id", businessId)
96	    .order("date", { ascending: false });
97	  if (fromIso) txQuery = txQuery.gte("date", fromIso);
98	  if (toIsoExclusive) txQuery = txQuery.lt("date", toIsoExclusive);
99	  const { data: transactions } = await txQuery;
100	
101	  const txList = transactions ?? [];
102	  const validTx = txList.filter((t) => !t.voided);
103	  const voidCount = txList.length - validTx.length;
104	
105	  // ── KPI utama ──
106	  const revenue = validTx.reduce((s, t) => s + Number(t.total), 0);
107	  const count = validTx.length;
108	  const avg = count > 0 ? Math.round(revenue / count) : 0;
109	  const totalItems = validTx.reduce(
110	    (s, t) => s + t.transaction_items.reduce((a, i) => a + Number(i.qty), 0),
111	    0,
112	  );
113	
114	  // ── Laba kotor & margin — hanya dari transaksi yang punya data modal (total_cost > 0),
115	  // supaya produk tanpa harga modal tidak dihitung margin 100% dan menyesatkan. ──
116	  const txWithCost = validTx.filter((t) => Number(t.total_cost) > 0);
117	  const grossProfit = txWithCost.reduce((s, t) => s + Number(t.gross_profit), 0);
118	  const revenueWithCost = txWithCost.reduce((s, t) => s + Number(t.subtotal), 0);
119	  const avgMargin =
120	    revenueWithCost > 0 ? Math.round((grossProfit / revenueWithCost) * 100) : null;
121	  const missingCostCount = validTx.length - txWithCost.length;
122	
123	  // ── Tunai vs non-tunai ──
124	  let cashRev = 0;
125	  let nonCashRev = 0;
126	  for (const t of validTx) {
127	    for (const p of t.transaction_payments) {
128	      if (p.method === "Tunai") cashRev += Number(p.amount);
129	      else nonCashRev += Number(p.amount);
130	    }
131	  }
132	
133	  // ── Penjualan per jam (WIB) ──
134	  const hourly = Array<number>(24).fill(0);
135	  for (const t of validTx) {
136	    hourly[wibHour(t.date)] += Number(t.total);
137	  }
138	  const hourlyMax = Math.max(...hourly, 1);
139	  const currentHour = wibHour(new Date().toISOString());
140	
141	  // ── Metode pembayaran ──
142	  const byMethod = new Map<string, number>();
143	  for (const t of validTx) {
144	    for (const p of t.transaction_payments) {
145	      byMethod.set(p.method, (byMethod.get(p.method) ?? 0) + Number(p.amount));
146	    }
147	  }
