  if (fromIso) txQuery = txQuery.gte("date", fromIso);
  if (toIsoExclusive) txQuery = txQuery.lt("date", toIsoExclusive);
  const { data: ticketTransactions } = await txQuery;

  const txMap = new Map((ticketTransactions ?? []).map((t) => [t.id, t]));
