  .from("businesses")
  .insert({
    owner_id: signInData.user.id,
    name: "Kolam Renang Test",
    business_type: "tiket",
  })
  .select("id, name, business_type")
  .single();

if (insertError) {
  console.error("insert error:", insertError.message);
  process.exit(1);
}

console.log(JSON.stringify(business));

