        ← Kembali
      </Link>
      <button
        onClick={() => window.print()}
        className="flex-1 rounded-xl bg-brand-600 py-2.5 text-sm font-semibold text-white hover:bg-brand-700"
      >
        🖨️ Cetak
      </button>
    </div>
  );
}

