11	import VoidTicketButton from "./void-ticket-button";
12	
13	function formatRupiah(value: number) {
14	  const sign = value < 0 ? "-" : "";
15	  return `${sign}Rp${Math.round(Math.abs(value)).toLocaleString("id-ID")}`;
16	}
17	
18	function formatDateTime(iso: string) {
19	  return new Date(iso).toLocaleString("id-ID", {
20	    day: "2-digit",
21	    month: "short",
22	    hour: "2-digit",
23	    minute: "2-digit",
24	    timeZone: "Asia/Jakarta",
25	  });
26	}
27	
28	export default async function TicketReportsPage({
29	  params,
30	  searchParams,
31	}: {
32	  params: Promise<{ businessId: string }>;
33	  searchParams: Promise<{
34	    period?: string;
35	    from?: string;
36	    to?: string;
37	    category?: string;
38	    serialFrom?: string;
39	    serialTo?: string;
40	  }>;
41	}) {
42	  const { businessId } = await params;
43	  const {
44	    period: periodParam,
45	    from,
46	    to,
47	    category: categoryFilter,
48	    serialFrom,
49	    serialTo,
50	  } = await searchParams;
51	  const period = parsePeriod(periodParam);
52	  const { fromIso, toIsoExclusive } = getPeriodRange(period, from, to);
53	
54	  const supabase = await createClient();
55	
56	  const { data: business } = await supabase
57	    .from("businesses")
58	    .select("id, name")
59	    .eq("id", businessId)
60	    .single();
61	
62	  if (!business) {
63	    notFound();
64	  }
65	
66	  const { data: categories } = await supabase
67	    .from("ticket_categories")
68	    .select("id, name")
69	    .eq("business_id", businessId)
70	    .is("deleted_at", null)
71	    .order("name", { ascending: true });
72	
73	  const today = new Date().toISOString().slice(0, 10);
74	  const { count: activeMemberCount } = await supabase
75	    .from("members")
76	    .select("id", { count: "exact", head: true })
77	    .eq("business_id", businessId)
78	    .is("deleted_at", null)
79	    .gte("valid_until", today);
80	
81	  let txQuery = supabase
82	    .from("ticket_transactions")
83	    .select("id, invoice_number, date, total, voided")
84	    .eq("business_id", businessId)
85	    .order("date", { ascending: false });
86	  if (fromIso) txQuery = txQuery.gte("date", fromIso);
87	  if (toIsoExclusive) txQuery = txQuery.lt("date", toIsoExclusive);
88	  const { data: ticketTransactions } = await txQuery;
89	
90	  const txMap = new Map((ticketTransactions ?? []).map((t) => [t.id, t]));
91	  const txIds = Array.from(txMap.keys());
92	
93	  let serials: {
94	    id: string;
95	    serial_no: number;
96	    price: number;
97	    is_member_price: boolean;
98	    ticket_transaction_id: string;
99	    ticket_categories: { name: string } | null;
100	  }[] = [];
101	
102	  if (txIds.length > 0) {
103	    let serialQuery = supabase
104	      .from("ticket_serials")
105	      .select("id, serial_no, price, is_member_price, ticket_transaction_id, ticket_categories(name)")
106	      .in("ticket_transaction_id", txIds)
107	      .order("serial_no", { ascending: true });
108	    if (categoryFilter) serialQuery = serialQuery.eq("ticket_category_id", categoryFilter);
109	    if (serialFrom) serialQuery = serialQuery.gte("serial_no", Number(serialFrom));
110	    if (serialTo) serialQuery = serialQuery.lte("serial_no", Number(serialTo));
111	    const { data } = await serialQuery;
112	    serials = (data ?? []) as unknown as typeof serials;
113	  }
114	
115	  const rows = serials
116	    .map((s) => ({ ...s, tx: txMap.get(s.ticket_transaction_id) }))
117	    .filter((s) => s.tx !== undefined) as (typeof serials[number] & {
118	    tx: { id: string; invoice_number: string; date: string; total: number; voided: boolean };
119	  })[];
120	
121	  const validRows = rows.filter((r) => !r.tx.voided);
122	  const totalTickets = validRows.length;
123	  const totalRevenue = validRows.reduce((s, r) => s + Number(r.price), 0);
124	
125	  const byCategory = new Map<string, { qty: number; revenue: number }>();
126	  for (const r of validRows) {
127	    const name = r.ticket_categories?.name ?? "Lainnya";
128	    const entry = byCategory.get(name) ?? { qty: 0, revenue: 0 };
129	    entry.qty += 1;
130	    entry.revenue += Number(r.price);
131	    byCategory.set(name, entry);
132	  }
133	  const categorySummary = Array.from(byCategory.entries()).sort((a, b) => b[1].revenue - a[1].revenue);
134	
135	  const filterQuery = new URLSearchParams();
136	  if (categoryFilter) filterQuery.set("category", categoryFilter);
137	  if (serialFrom) filterQuery.set("serialFrom", serialFrom);
138	  if (serialTo) filterQuery.set("serialTo", serialTo);
139	
140	  return (
141	    <div className="w-full max-w-3xl">
142	      <div className="flex flex-wrap items-center justify-between gap-2">
143	        <div>
144	          <h1 className="text-lg font-bold text-zinc-900">Laporan Tiket — {business.name}</h1>
145	          <p className="mt-0.5 text-xs text-zinc-500">{PERIOD_DESCRIPTIONS[period]}</p>
146	        </div>
147	        <div className="flex flex-wrap gap-1.5">
148	          {(["today", "week", "month", "all", "custom"] as Period[]).map((p) => (
149	            <Link
150	              key={p}
151	              href={`/business/${businessId}/ticket-reports?period=${p}&${filterQuery.toString()}`}
152	              className={`rounded-full px-3 py-1 text-xs font-medium transition-colors ${
153	                p === period ? "bg-brand-600 text-white" : "bg-white text-zinc-600 hover:bg-zinc-100"
154	              }`}
155	            >
156	              {PERIOD_LABELS[p]}
157	            </Link>
158	          ))}
159	        </div>
160	      </div>
161	
162	      {/* KPI */}
163	      <div className="mt-6 grid grid-cols-2 gap-3 sm:grid-cols-3">
164	        <div className="rounded-2xl bg-brand-700 p-4">
165	          <p className="mb-1.5 text-[10.5px] font-semibold uppercase text-brand-200">
166	            Anggota Aktif
167	          </p>
168	          <p className="text-2xl font-bold text-white">{activeMemberCount ?? 0}</p>
169	        </div>
170	        <div className="rounded-2xl border border-zinc-200 bg-white p-4">
171	          <p className="mb-1.5 text-[10.5px] font-semibold uppercase text-zinc-400">
172	            Tiket Terjual
173	          </p>
174	          <p className="text-2xl font-bold text-zinc-900">{totalTickets}</p>
175	        </div>
176	        <div className="rounded-2xl border border-zinc-200 bg-white p-4">
177	          <p className="mb-1.5 text-[10.5px] font-semibold uppercase text-zinc-400">Pendapatan</p>
178	          <p className="text-xl font-bold text-zinc-900">{formatRupiah(totalRevenue)}</p>
179	        </div>
180	      </div>
181	
182	      {/* Filter */}
183	      <form
184	        method="get"
185	        className="mt-4 flex flex-wrap items-end gap-3 rounded-2xl border border-zinc-200 bg-white p-4"
186	      >
187	        <input type="hidden" name="period" value={period} />
188	        {period === "custom" && (
189	          <>
190	            <label className="text-xs font-medium text-zinc-600">
191	              Dari
192	              <input
193	                type="date"
194	                name="from"
195	                defaultValue={from}
196	                className="mt-1 block rounded-lg border border-zinc-200 px-2 py-1.5 text-sm"
197	              />
198	            </label>
199	            <label className="text-xs font-medium text-zinc-600">
200	              Sampai
201	              <input
202	                type="date"
203	                name="to"
204	                defaultValue={to}
205	                className="mt-1 block rounded-lg border border-zinc-200 px-2 py-1.5 text-sm"
206	              />
207	            </label>
208	          </>
209	        )}
210	        <label className="text-xs font-medium text-zinc-600">
211	          Kategori
212	          <select
213	            name="category"
214	            defaultValue={categoryFilter ?? ""}
215	            className="mt-1 block rounded-lg border border-zinc-200 px-2 py-1.5 text-sm"
216	          >
217	            <option value="">Semua kategori</option>
218	            {(categories ?? []).map((c) => (
219	              <option key={c.id} value={c.id}>
220	                {c.name}
221	              </option>
222	            ))}
223	          </select>
224	        </label>
225	        <label className="text-xs font-medium text-zinc-600">
226	          No. Seri Dari
227	          <input
228	            type="number"
229	            name="serialFrom"
230	            min="1"
231	            defaultValue={serialFrom}
232	            className="mt-1 block w-24 rounded-lg border border-zinc-200 px-2 py-1.5 text-sm"
233	          />
234	        </label>
235	        <label className="text-xs font-medium text-zinc-600">
236	          No. Seri Sampai
237	          <input
238	            type="number"
239	            name="serialTo"
240	            min="1"
241	            defaultValue={serialTo}
242	            className="mt-1 block w-24 rounded-lg border border-zinc-200 px-2 py-1.5 text-sm"
243	          />
244	        </label>
245	        <button
246	          type="submit"
247	          className="rounded-lg bg-brand-600 px-4 py-2 text-xs font-semibold text-white hover:bg-brand-700"
248	        >
249	          Terapkan
250	        </button>
251	      </form>
252	
253	      {/* Ringkasan per kategori */}
254	      <div className="mt-4 rounded-2xl border border-zinc-200 bg-white p-4">
255	        <h2 className="text-sm font-bold text-zinc-900">Ringkasan per Kategori</h2>
256	        {categorySummary.length > 0 ? (
257	          <div className="mt-3 space-y-2">
258	            {categorySummary.map(([name, s]) => (
259	              <div key={name} className="flex items-center justify-between text-sm">
260	                <span className="font-medium text-zinc-700">
261	                  {name} <span className="text-zinc-400">({s.qty} tiket)</span>
262	                </span>
263	                <span className="font-bold text-zinc-900">{formatRupiah(s.revenue)}</span>
264	              </div>
265	            ))}
266	          </div>
267	        ) : (
268	          <p className="py-4 text-center text-xs text-zinc-300">Belum ada data</p>
269	        )}
270	      </div>
271	
272	      {/* Rekonsiliasi nomor seri */}
273	      <div className="mt-4 overflow-hidden rounded-2xl border border-zinc-200 bg-white">
274	        <div className="flex items-center justify-between border-b border-zinc-100 px-4 py-3.5">
275	          <h2 className="text-sm font-bold text-zinc-900">Rekonsiliasi Tiket</h2>
276	          <span className="text-[10.5px] font-semibold uppercase text-zinc-400">
277	            {rows.length} tiket
278	          </span>
279	        </div>
280	        {rows.length > 0 ? (
281	          <div className="divide-y divide-zinc-100">
282	            {(() => {
283	              const shownVoidFor = new Set<string>();
284	              return rows.slice(0, 100).map((r) => {
285	                const showVoidButton = !r.tx.voided && !shownVoidFor.has(r.tx.id);
286	                if (showVoidButton) shownVoidFor.add(r.tx.id);
287	                return (
288	                  <div
289	                    key={r.id}
290	                    className={`relative px-4 py-3 ${r.tx.voided ? "opacity-60" : ""}`}
291	                  >
292	                    <div className="flex items-center justify-between gap-3">
293	                      <div className="min-w-0">
294	                        <p className="text-[13px] font-semibold text-zinc-900">
295	                          #{r.serial_no} — {r.ticket_categories?.name ?? "Lainnya"}
296	                          {r.is_member_price && (
297	                            <span className="ml-1.5 rounded-full bg-brand-50 px-1.5 py-0.5 text-[10px] font-semibold text-brand-700">
298	                              Member
299	                            </span>
300	                          )}
301	                          {r.tx.voided && (
302	                            <span className="ml-1.5 rounded-full bg-red-100 px-1.5 py-0.5 text-[10px] font-bold text-red-600">
