450	            <div className="flex items-center justify-between text-xs text-zinc-500">
451	              <span>PPN ({taxRate}%)</span>
452	              <span className="tabular-nums">{formatRupiah(taxAmt)}</span>
453	            </div>
454	          )}
455	          <div className="flex items-center justify-between pt-1 text-sm font-semibold text-zinc-900">
456	            <span>Total</span>
457	            <span className="tabular-nums">{formatRupiah(total)}</span>
458	          </div>
459	        </div>
460	
461	        {!paying ? (
462	          <>
463	            <button
464	              onClick={() => setPaying(true)}
465	              disabled={cartLines.length === 0}
466	              className="mt-3 w-full rounded-xl bg-brand-600 py-2.5 text-sm font-semibold text-white transition-colors hover:bg-brand-700 disabled:cursor-not-allowed disabled:opacity-50"
