async function handleLookupMember() {
  setMemberError(null);
  setMemberBusy(true);
  const result = await lookupMemberByCode(businessId, memberCode);
  setMemberBusy(false);
  if (!result.success) {
    setMemberError(result.error);
    return;
  }
  setMember(result.member);
